<script setup lang="ts">
import {computed,onScopeDispose,ref,shallowRef,watch} from 'vue'
import {can,currentProject,projectId,session} from '@/core/session'
import {ApiError,IdentityChanged,errorMessage,identityEpoch,onIdentityChange} from '@/core/http'
import {formatTime} from '@/core/time'
import {showOperationFeedback} from '@/ui/operation-feedback'
import {typeDeviceUuid} from './type-devices-api'
import {privateTemplateTransport,type PrivateTemplateTransport,type PrivateTemplateDirectory,type PrivateTemplateVersions,type PrivateTemplateVersion} from './private-template-api'
import {productTransport,prepareProductPublish,prepareProductWithdraw,productPublicationMatches,type ProductTransport,type OwnedProducts,type OwnedProduct,type ProductPublishIntent,type ProductWithdrawIntent,type ProductPublication} from './public-product-api'
const props=withDefaults(defineProps<{typeId:string;disabled?:boolean;withdrawOnly?:boolean;ownedProduct?:OwnedProduct;transport?:ProductTransport;templates?:PrivateTemplateTransport}>(),{disabled:false,withdrawOnly:false,transport:()=>productTransport,templates:()=>privateTemplateTransport})
const emit=defineEmits<{locked:[value:boolean];refreshProducts:[]}>(),roles=['OWNER','ADMIN','OPERATOR','VIEWER']
const denied=ref(false),member=computed(()=>session.ready&&!session.transitioning&&!!session.user?.accountId&&typeDeviceUuid.test(projectId.value)&&typeDeviceUuid.test(props.typeId)&&can('device:read')&&roles.includes(session.user?.projectRole||'')&&roles.includes(currentProject.value?.myRole||''))
const readable=computed(()=>member.value&&!denied.value),manager=computed(()=>readable.value&&['OWNER','ADMIN'].includes(session.user?.projectRole||'')&&['OWNER','ADMIN'].includes(currentProject.value?.myRole||'')),publishable=computed(()=>manager.value&&currentProject.value?.status==='ACTIVE'&&records.value?.available===true)
const records=shallowRef<OwnedProducts>(),own=computed(()=>props.withdrawOnly?props.ownedProduct:records.value?.items.find(row=>row.sourceDeviceTypeId===props.typeId)),previous=shallowRef<OwnedProduct|null>(null)
const directory=shallowRef<PrivateTemplateDirectory>(),versions=shallowRef<PrivateTemplateVersions>(),source=shallowRef<PrivateTemplateVersion>(),intent=shallowRef<ProductPublishIntent|ProductWithdrawIntent>(),observed=shallowRef<ProductPublication>()
const shown=ref(false),kind=ref<'publish'|'withdraw'>('publish'),busy=ref(false),unknown=ref(false),label=ref(''),acknowledged=ref(false),error=ref(''),notice=ref(''),chosen=ref('')
const locked=computed(()=>shown.value||busy.value||unknown.value)
let generation=0,alive=true,controller:AbortController|undefined
function clear(){generation++;controller?.abort();records.value=undefined;previous.value=null;directory.value=undefined;versions.value=undefined;source.value=undefined;intent.value=undefined;observed.value=undefined;shown.value=false;busy.value=false;unknown.value=false;label.value='';acknowledged.value=false;error.value='';notice.value='';chosen.value=''}
function capture(){return{generation,epoch:identityEpoch(),project:projectId.value,type:props.typeId,account:session.user?.accountId}}
function current(s:ReturnType<typeof capture>){return alive&&readable.value&&s.generation===generation&&s.epoch===identityEpoch()&&s.project===projectId.value&&s.type===props.typeId&&s.account===session.user?.accountId}
function fail(cause:unknown,s:ReturnType<typeof capture>){if(!current(s)||cause instanceof IdentityChanged)return;if(cause instanceof ApiError&&[401,403].includes(cause.status)&&!cause.outcomeUnknown){clear();denied.value=true}else error.value=errorMessage(cause)}
async function load(){if(!readable.value||busy.value||unknown.value||shown.value)return;if(props.withdrawOnly){emit('refreshProducts');return}const s=capture();busy.value=true;controller=new AbortController();error.value='';try{const actual=await props.transport.owned(s.project,controller.signal);if(current(s))records.value=actual}catch(cause){fail(cause,s)}finally{if(current(s))busy.value=false}}
function reset(){clear();denied.value=false;if(readable.value&&!props.withdrawOnly)void load()}
async function openPublish(){if(props.withdrawOnly||!publishable.value||props.disabled||locked.value)return;shown.value=true;kind.value='publish';previous.value=own.value??null;label.value=own.value?.product.publisherLabel??'';acknowledged.value=false;source.value=undefined;versions.value=undefined;directory.value=undefined;notice.value='';error.value='';const s=capture();busy.value=true;controller=new AbortController();try{const rows=await props.templates.directory(s.project,controller.signal);if(current(s))directory.value=rows}catch(cause){fail(cause,s)}finally{if(current(s))busy.value=false}}
function openWithdraw(){if(!manager.value||props.disabled||locked.value||own.value?.product.state!=='PUBLISHED')return;shown.value=true;kind.value='withdraw';previous.value=own.value;acknowledged.value=false;error.value='';notice.value=''}
function close(){if(busy.value)return;if(unknown.value)shown.value=false;else{shown.value=false;source.value=undefined;previous.value=null;directory.value=undefined;versions.value=undefined;acknowledged.value=false;error.value=''}}
function beforeClose(done:()=>void){if(!busy.value&&!(props.withdrawOnly&&unknown.value)){close();done()}}
async function selectTemplate(id:string){if(!publishable.value||props.disabled||busy.value||unknown.value||!directory.value?.items.some(row=>row.id===id))return;chosen.value=id;versions.value=undefined;source.value=undefined;acknowledged.value=false;const s=capture();busy.value=true;controller=new AbortController();try{const rows=await props.templates.versions(s.project,id,controller.signal);if(current(s))versions.value=rows}catch(cause){fail(cause,s)}finally{if(current(s))busy.value=false}}
async function selectVersion(id:string){if(!publishable.value||props.disabled||busy.value||unknown.value||!versions.value?.items.some(row=>row.versionId===id&&row.sourceDeviceTypeId===props.typeId))return;const s=capture();busy.value=true;source.value=undefined;acknowledged.value=false;error.value='';controller=new AbortController();try{const fixed=await props.templates.version(s.project,id,controller.signal);if(!current(s))return;const row=versions.value?.items.find(v=>v.versionId===id);if(fixed.sourceDeviceTypeId!==s.type||fixed.templateId!==chosen.value||fixed.packageDigest!==row?.packageDigest)throw new Error('固定来源与当前类型不符，请重新读取');source.value=fixed}catch(cause){fail(cause,s)}finally{if(current(s))busy.value=false}}
function completePublication(value:ProductPublication){unknown.value=false;intent.value=undefined;busy.value=false;shown.value=false;notice.value=`本次发布第 ${value.product.sequence} 版已确认，产品ID为 ${value.product.productId}。当前可用状态按下方刷新事实显示。`}
async function confirm(){if(!shown.value||busy.value||unknown.value||props.disabled||!manager.value||!acknowledged.value)return;let original:ProductPublishIntent|ProductWithdrawIntent
 try{if(kind.value==='publish'){if(!publishable.value||!source.value)throw new Error('请选择当前类型的精确私有模板版本');original=prepareProductPublish(projectId.value,source.value,previous.value,label.value)}else{if(!previous.value)throw new Error('请先刷新当前产品');original=prepareProductWithdraw(projectId.value,previous.value)}}catch(cause){error.value=errorMessage(cause);return}
 intent.value=original;unknown.value=true;busy.value=true;error.value='';const s=capture();controller=new AbortController();let accepted=false
 try{if(original.kind==='publish'){const returned=await props.transport.publish(original,controller.signal);accepted=true;if(!current(s))return;if(!productPublicationMatches(returned,original))throw new Error('本次发布回执不符');const actual=await props.transport.published(original,controller.signal);if(!current(s))return;if(returned.product.versionId!==actual.product.versionId||!productPublicationMatches(actual,original))throw new Error('本次发布原件不一致');completePublication(actual)}else{await props.transport.withdraw(original,controller.signal);accepted=true;if(!current(s))return;unknown.value=false;intent.value=undefined;busy.value=false;shown.value=false;notice.value='本次撤回已确认，当前状态按下方刷新事实显示；再次发布沿用原产品ID。';if(props.withdrawOnly)showOperationFeedback('产品已撤回')}}
 catch(cause){if(current(s)&&!(cause instanceof IdentityChanged)){if(!accepted&&cause instanceof ApiError&&!cause.outcomeUnknown&&cause.code!==10014&&cause.status>=400&&cause.status<500){unknown.value=false;intent.value=undefined;if([401,403].includes(cause.status)){fail(cause,s);return}}error.value=errorMessage(cause)}}finally{if(current(s)){busy.value=false;if(notice.value)void load()}}}
async function recover(){const original=intent.value;if(!original||!unknown.value||busy.value||!readable.value)return;const s=capture();busy.value=true;error.value='';controller=new AbortController();try{if(original.kind==='publish'){const actual=await props.transport.published(original,controller.signal);if(current(s)){if(!productPublicationMatches(actual,original))throw new Error('原发布版本不符');completePublication(actual)}}else{const actual=await props.transport.current(original.project,original.source.product.productId,controller.signal);if(current(s))observed.value=actual}}
 catch(cause){if(current(s)&&cause instanceof ApiError&&cause.status===404)error.value='暂未读到原件；当前仍保持未知，不会再次提交。';else fail(cause,s)}finally{if(current(s)){busy.value=false;if(notice.value)void load()}}}
function finish(){if(!unknown.value||busy.value)return;unknown.value=false;intent.value=undefined;observed.value=undefined;shown.value=false;notice.value='已结束本次核对；原操作仍未确认，未标记成功。';if(props.withdrawOnly)showOperationFeedback('已结束核对，原撤回结果仍未确认','warning');void load()}
watch([()=>projectId.value,()=>props.typeId,()=>session.user?.accountId,()=>member.value],reset,{immediate:true,flush:'sync'})
watch(locked,value=>emit('locked',value),{immediate:true,flush:'sync'})
const dispose=onIdentityChange(reset);onScopeDispose(()=>{alive=false;clear();dispose();emit('locked',false)})
</script>
<template><section class="product-publisher">
 <template v-if="withdrawOnly"><el-button v-if="manager&&own?.product.state==='PUBLISHED'" size="small" type="danger" :disabled="disabled||locked" @click="openWithdraw">撤回</el-button></template>
 <template v-else><header><h3>按产品ID分享</h3><el-button v-if="manager" :disabled="disabled||locked||!publishable" @click="openPublish">{{own?'更新或重新发布':'发布固定版本'}}</el-button></header><p>从本类型已保存的私有模板版本中明确选择资料。发布后由您决定是否分享产品ID，本页不会列入平台公开目录；同一类型更新或撤回后再发布沿用原ID。</p>
  <p v-if="records&&!records.available">当前未开放新的产品ID分享；已有原件仍可核对，归属管理者仍可撤回。</p><p v-if="!own&&records">本类型尚无产品ID。</p>
  <template v-if="own"><p>产品ID：{{own.product.productId}}</p><p>当前：{{own.product.state==='PUBLISHED'?'可凭ID使用':'已撤回'}} · 发布第 {{own.product.sequence}} 版 · {{formatTime(own.product.publishedAt)}}</p><p>当前发布版本：{{own.product.versionId}} · 包摘要：{{own.product.packageDigest}}</p><el-button v-if="manager&&own.product.state==='PUBLISHED'" size="small" :disabled="disabled||locked" @click="openWithdraw">撤回产品分享</el-button></template>
  <el-button size="small" :loading="busy&&!shown" :disabled="!readable||locked" @click="load">刷新本类型分享状态</el-button><el-alert v-if="error&&!shown" :title="error" type="error" :closable="false"/>
 </template>
 <el-alert v-if="notice&&!withdrawOnly" :title="notice" type="info" :closable="false"/>
 <el-alert v-if="unknown&&!shown" title="存在尚未确认的产品操作。" type="warning" :closable="false"><el-button @click="shown=true">查看原产品操作核对</el-button></el-alert>
 <el-dialog :model-value="shown&&readable" :title="kind==='publish'?'发布固定类型资料':'撤回产品分享'" :width="withdrawOnly?'min(500px,94vw)':'min(900px,96vw)'" :append-to-body="withdrawOnly" :close-on-click-modal="false" :close-on-press-escape="!busy&&!(withdrawOnly&&unknown)" :show-close="!busy&&!(withdrawOnly&&unknown)" :before-close="beforeClose"><el-alert v-if="error" :title="error" type="error" :closable="false"/>
  <template v-if="unknown"><el-alert title="原操作尚未确认；不会再次提交。" type="warning" :closable="false"/><p>原请求键：{{intent?.key}}</p><p v-if="intent?.kind==='publish'">原私有模板版本：{{intent.source.versionId}} · 摘要：{{intent.source.packageDigest}}</p><p v-else-if="intent?.kind==='withdraw'">原产品ID：{{intent.source.product.productId}} · 原版本：{{intent.body.revision}}</p><p v-if="observed">当前读取：{{observed.product.state==='PUBLISHED'?'可凭ID使用':'已撤回'}} · 当前版本 {{observed.product.currentVersionId}}。当前状态不能证明原撤回请求结果。</p><el-button :loading="busy" @click="recover">{{intent?.kind==='publish'?'读取原发布回执':'读取当前产品核对'}}</el-button><el-button :disabled="busy" @click="finish">结束本次产品操作核对</el-button></template>
  <template v-else-if="kind==='publish'"><p v-if="previous">将更新产品 {{previous.product.productId}}；原状态为{{previous.product.state==='PUBLISHED'?'可使用':'已撤回'}}，已有目标类型不自动更新。</p><p v-else>本次首次发布将生成稳定产品ID。</p><p>仅可选择当前类型已保存的草稿固定资料，不代表当前已发布物模型；需要更新时先保存新的私有模板版本。</p>
   <el-table :data="directory?.items||[]" empty-text="暂无私有模板，请先保存草稿模板"><el-table-column prop="name" label="私有模板"/><el-table-column width="120"><template #default="{row}"><el-button :disabled="disabled||busy||!publishable" @click="selectTemplate(row.id)">选择模板来源</el-button></template></el-table-column></el-table>
   <el-table v-if="versions" :data="versions.items" empty-text="暂无版本"><el-table-column prop="sequence" label="模板版本" width="100"/><el-table-column label="保存时间"><template #default="{row}">{{formatTime(row.createdAt)}}</template></el-table-column><el-table-column width="150"><template #default="{row}"><el-button :disabled="disabled||busy||!publishable||row.sourceDeviceTypeId!==typeId" @click="selectVersion(row.versionId)">{{row.sourceDeviceTypeId===typeId?'选择此固定版本':'其它来源类型'}}</el-button></template></el-table-column></el-table>
   <template v-if="source"><p>已选：{{source.templateName}} 第 {{source.sequence}} 版 · {{source.versionId}}</p><p>完整包摘要：{{source.packageDigest}}</p><details open><summary>完整分享内容（含描述与标签）</summary><pre aria-label="待分享完整固定资料" tabindex="0">{{source.packageJson}}</pre></details><p>本次只分享基本资料和属性、事件、命令。扩展定义、规则、任务、数据流、Modbus和App配置未携带；密钥和设备不复制。</p><el-form label-position="top" :disabled="busy||disabled||!publishable"><el-form-item label="分享署名（自述）"><el-input v-model="label" aria-label="产品分享署名" maxlength="80"/></el-form-item><el-checkbox v-model="acknowledged" aria-label="确认分享完整固定资料">我已核对完整资料，了解获得此ID的已登录项目成员可以读取并创建此版本类型。</el-checkbox></el-form><p>当前平台每产品最多20个发布版本。确认会生成下一固定发布版本；当前资料此后变化不自动同步，撤回可停止后继复制。</p></template>
  </template>
  <template v-else><p>确认撤回已发布的产品吗？撤回后，其他用户将无法通过该产品 ID 创建设备类型。您可以随后再次发布，产品 ID 将保持不变。</p><el-checkbox v-model="acknowledged" aria-label="确认撤回产品分享" :disabled="busy||disabled||!manager">确认撤回当前产品分享</el-checkbox></template>
  <template #footer><el-button v-if="!(withdrawOnly&&unknown)" :disabled="busy" @click="close">{{unknown?'关闭核对':'取消'}}</el-button><el-button v-if="!unknown&&manager" :type="withdrawOnly?'danger':'primary'" :loading="busy" :disabled="busy||disabled||!acknowledged||(kind==='publish'&&(!publishable||!source))" @click="confirm">{{kind==='publish'?'确认发布此固定版本':'确认撤回产品分享'}}</el-button></template>
 </el-dialog></section></template>
<style scoped>.product-publisher header{display:flex;justify-content:space-between;align-items:center;gap:12px}.product-publisher h3{font-size:18px;font-weight:500}.product-publisher p{font-size:13px;line-height:1.7;color:var(--tl-muted);overflow-wrap:anywhere}.product-publisher pre{max-height:330px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;background:var(--tl-bg);padding:12px;font-size:12px;line-height:1.6}.product-publisher :deep(.el-alert){margin:12px 0}</style>
